/*
 * 14-exam-results.sql — exam results for the seeded examinations.
 *
 *   ACCP-DEMO  8 students x 8 exams = 64 results. Per-exam averages trace
 *              the mountain 55 -> 87 -> 61 (peak at exam 5). Grades cover A..F.
 *   Other     1 row per (exam, enrolled candidate), grades cover A..F.
 *
 * Idempotent on (ExamId, EnrollmentId). Requires examinations + enrollments.
 */

SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET NOCOUNT ON;
SET XACT_ABORT ON;
