;WITH AllResults AS (
    SELECT s.ExamId, de.EnrollmentId, s.Score
    FROM @DemoScores s
    INNER JOIN @DemoEnrollments de ON de.Slot = s.Slot
    UNION ALL
    SELECT ExamId, EnrollmentId, Score FROM @OtherScores
)
INSERT INTO exam_result (Id, ExamId, EnrollmentId, Score, Grade, IsPassed, IsFinalized,
                         GradedById, IsOverridden, OverrideById, OverrideReason, GradedAt,
                         CreatedAt, CreatedBy, UpdatedAt, UpdatedBy)
SELECT
    NEWID(), r.ExamId, r.EnrollmentId, r.Score,
    CASE WHEN r.Score >= 85 THEN N'A'
         WHEN r.Score >= 70 THEN N'B'
         WHEN r.Score >= 55 THEN N'C'
         WHEN r.Score >= 40 THEN N'D'
         ELSE                    N'F' END,
    CASE WHEN r.Score >= 50 THEN 1 ELSE 0 END,
    1, @DemoFacultyStaff, 0, NULL, NULL, @Now,
    @Now, @Seeder, NULL, NULL
FROM AllResults r
WHERE NOT EXISTS (
    SELECT 1 FROM exam_result x
    WHERE x.ExamId = r.ExamId AND x.EnrollmentId = r.EnrollmentId
);

COMMIT TRAN;
PRINT '14-exam-results.sql: ~80 exam_result rows ensured (demo mountain + other batches).';
